// Warum ein eigener Hash statt require('crypto'):
// n8n erlaubt eingebaute Node-Module im Code-Node nur, wenn der Betreiber
// NODE_FUNCTION_ALLOW_BUILTIN gesetzt hat — auf n8n Cloud geht das gar nicht.
// Der Hash muss hier nicht faelschungssicher sein, er muss nur zuverlaessig
// anzeigen, ob sich der Text seit dem letzten Lauf geaendert hat. Dafuer reicht FNV-1a.
function fnv1a(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const doku = $('Dokumente einzeln verarbeiten').first().json;
const text = String($input.first().json.text || '');

// Normalisieren, bevor gehasht wird: unterschiedliche Zeilenenden oder nachlaufende
// Leerzeichen aus einem neuen PDF-Export wuerden sonst eine Aenderung vortaeuschen
// und das ganze Dokument unnoetig neu einbetten.
const normalisiert = text.replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// Laenge mit in den Hash: schuetzt gegen die (seltenen) FNV-Kollisionen,
// kostet nichts und macht das Ergebnis im Sheet fuer Menschen nachvollziehbar.
const neuerHash = fnv1a(normalisiert) + '-' + normalisiert.length.toString(16);
const alterHash = String(doku.inhalt_hash || '').trim();

if (normalisiert.length < 200) {
  // Ein PDF ohne Textebene (reiner Scan) liefert leeren Text. Ohne diese Bremse
  // wuerde der Workflow den Eintrag als "geaendert" behandeln und leere Abschnitte indexieren.
  throw new Error('Dokument "' + (doku.name || doku.dokument_id) + '" liefert kaum Text (' +
    normalisiert.length + ' Zeichen) — vermutlich ein Scan ohne OCR. Bitte OCR vorschalten.');
}

return [{
  json: {
    dokument_id: String(doku.dokument_id || doku.name || '').trim(),
    dokument_name: doku.name,
    quelle_url: doku.url,
    inhalt_hash: neuerHash,
    vorher_hash: alterHash,
    geaendert: neuerHash !== alterHash,
    zeichen: normalisiert.length,
    stand: new Date().toISOString().slice(0, 10),
    text: normalisiert,
  },
}];

// Warum ueberhaupt Abschnitte: Ein einziges Embedding ueber 30 Seiten verwaessert die
// Bedeutung — die Suche findet dann alles ein bisschen und nichts genau.
// ZIELGROESSE ~1200 Zeichen ist der Bereich, in dem ein Abschnitt noch genug Kontext
// mitbringt, aber thematisch eindeutig bleibt (grob 300 Token).
// UEBERLAPPUNG verhindert, dass eine Aussage, die genau auf der Schnittkante liegt,
// in beiden Abschnitten nur halb vorkommt und damit von der Suche nicht mehr gefunden wird.
const ZIELGROESSE = 1200;
const UEBERLAPPUNG = 200;
const MIN_ABSCHNITT = 80;

const raus = [];

for (const eintrag of $input.all()) {
  const dok = eintrag.json;
  const text = String(dok.text || '');
  let start = 0;
  let nummer = 0;

  while (start < text.length) {
    let ende = Math.min(start + ZIELGROESSE, text.length);

    if (ende < text.length) {
      // Lieber an einer Absatz- oder Satzgrenze schneiden als mitten im Wort.
      // Sonst beginnt ein Abschnitt mit einem Halbsatz und die KI zitiert spaeter Fragmente,
      // die im Original gar nicht so stehen.
      const fenster = text.slice(start, ende);
      const absatz = fenster.lastIndexOf('\n\n');
      const satz = Math.max(fenster.lastIndexOf('. '), fenster.lastIndexOf('! '), fenster.lastIndexOf('? '));
      if (absatz > ZIELGROESSE * 0.5) {
        ende = start + absatz;
      } else if (satz > ZIELGROESSE * 0.5) {
        ende = start + satz + 1;
      }
    }

    const abschnitt = text.slice(start, ende).trim();

    // Reste unter MIN_ABSCHNITT (Seitenzahlen, Fusszeilen) fliegen raus:
    // sie erzeugen Treffer ohne Aussage und verdraengen echte Fundstellen aus dem Top-K.
    if (abschnitt.length >= MIN_ABSCHNITT) {
      raus.push({
        json: {
          dokument_id: dok.dokument_id,
          dokument_name: dok.dokument_name,
          quelle_url: dok.quelle_url,
          inhalt_hash: dok.inhalt_hash,
          stand: dok.stand,
          abschnitt_nr: nummer,
          abschnitt_id: dok.dokument_id + '#' + nummer,
          text: abschnitt,
          zeichen: abschnitt.length,
        },
      });
      nummer++;
    }

    if (ende >= text.length) break;
    // start + 1 als Untergrenze: verhindert eine Endlosschleife, falls die Satzgrenze
    // den Schnitt weiter nach vorne zieht als die Ueberlappung zurueck.
    start = Math.max(ende - UEBERLAPPUNG, start + 1);
  }
}

if (raus.length === 0) {
  throw new Error('Keine verwertbaren Abschnitte gebildet — Dokument pruefen.');
}

return raus;

// Embeddings kommen in derselben Reihenfolge zurueck wie die Abschnitte hineingingen.
// Trotzdem wird die Anzahl geprueft: verrutscht die Zuordnung (z. B. weil ein Request
// gescheitert ist), landen Texte unter fremden Vektoren — ein Fehler, der im Betrieb
// nur als "die Suche liefert Unsinn" auffaellt und stundenlang Suche kostet.
const abschnitte = $('In Abschnitte teilen').all();
const antworten = $input.all();

if (abschnitte.length !== antworten.length) {
  throw new Error('Abschnitte (' + abschnitte.length + ') und Embeddings (' + antworten.length +
    ') passen nicht zusammen — Lauf abgebrochen, damit keine falsch verknuepften Vektoren entstehen.');
}

function fnv1a(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

const punkte = antworten.map((antwort, i) => {
  const a = abschnitte[i].json;
  const vektor = antwort.json?.data?.[0]?.embedding;
  if (!Array.isArray(vektor) || vektor.length === 0) {
    throw new Error('Kein Vektor fuer Abschnitt ' + a.abschnitt_id + ' erhalten.');
  }
  return {
    // Deterministische ID aus Dokument + Abschnittsnummer: ein zweiter Lauf ueberschreibt
    // denselben Punkt, statt eine Dublette anzulegen. Qdrant akzeptiert unsigned Integer.
    id: fnv1a(String(a.dokument_id)) * 100000 + a.abschnitt_nr,
    vector: vektor,
    payload: {
      dokument_id: a.dokument_id,
      dokument_name: a.dokument_name,
      quelle_url: a.quelle_url,
      abschnitt_nr: a.abschnitt_nr,
      stand: a.stand,
      text: a.text,
    },
  };
});

const erster = abschnitte[0].json;

return [{
  json: {
    dokument_id: erster.dokument_id,
    dokument_name: erster.dokument_name,
    quelle_url: erster.quelle_url,
    inhalt_hash: erster.inhalt_hash,
    stand: erster.stand,
    anzahl_abschnitte: punkte.length,
    points: punkte,
  },
}];
